import json, sys

def truncate(s, n=300):
    s = s.replace("\n", " ")
    return s if len(s) <= n else s[:n] + "...[truncated]"

def summarize(fname):
    print(f"\n\n########## {fname} ##########")
    with open(fname) as f:
        lines = [json.loads(l) for l in f if l.strip()]
    first_ts = None
    last_ts = None
    for entry in lines:
        ts = entry.get("timestamp")
        if ts:
            if first_ts is None:
                first_ts = ts
            last_ts = ts
        typ = entry.get("type")
        msg = entry.get("message")
        if typ == "user" and msg:
            content = msg.get("content")
            if isinstance(content, str):
                print(f"[{ts}] USER: {truncate(content)}")
            elif isinstance(content, list):
                for c in content:
                    if c.get("type") == "text":
                        print(f"[{ts}] USER: {truncate(c['text'])}")
                    elif c.get("type") == "tool_result":
                        cont = c.get("content")
                        if isinstance(cont, list):
                            for cc in cont:
                                if cc.get("type")=="text":
                                    print(f"[{ts}] TOOL_RESULT: {truncate(cc['text'],200)}")
                        elif isinstance(cont, str):
                            print(f"[{ts}] TOOL_RESULT: {truncate(cont,200)}")
        elif typ == "assistant" and msg:
            content = msg.get("content")
            if isinstance(content, list):
                for c in content:
                    if c.get("type") == "text":
                        print(f"[{ts}] ASSISTANT: {truncate(c['text'])}")
                    elif c.get("type") == "tool_use":
                        name = c.get("name")
                        inp = truncate(json.dumps(c.get("input",{})), 200)
                        print(f"[{ts}] TOOL_USE: {name} {inp}")
        elif entry.get("attachment"):
            att = entry["attachment"]
            hookname = att.get("hookName")
            if hookname:
                print(f"[{ts}] HOOK: {hookname}")
    print(f"\n-- span: {first_ts} to {last_ts} --")

for fname in sys.argv[1:]:
    summarize(fname)

